contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 seedAmount, uint256 kilos, address ref) public payable {
        require(ref != address(0));
        require(ref != address(this));
        require(seedAmount > 0);
        require(kilos > 0);

        uint256 totalBeforeRef = c.claimedDrugs(ref);
        uint256 marketBefore = c.marketDrugs();

        c.seedMarket{value: seedAmount}(kilos);

        c.collectDrugs(ref);

        uint256 totalAfterRef = c.claimedDrugs(ref);

        uint256 expectedIncrease = c.getMyDrugs() / 5;
        uint256 expectedMarket = marketBefore + c.getMyDrugs() / 10;

        assert(
            c.claimedDrugs(address(this)) == 0 &&
            totalAfterRef >= totalBeforeRef &&
            totalAfterRef - totalBeforeRef == expectedIncrease &&
            c.marketDrugs() == expectedMarket
        );
    }

    receive() external payable {}
}

